Suppose that Assumptions~ef{assump:smoothH} and ef{assump:near-linear} hold. With ${\hat{x}}_{n}$ and ${\hat{y}}_{n}$ defined in \eqref{alg:xyhat}, for any ${\delta_F}' \in (0, {\delta_F}]$, ${\delta_G}' \in (0, {\delta_G}]$ and ${\delta_H}' \in (0, {\delta_H}]$, we have the following results.  egin{enumerate}[(i)] \item $F({x}_{n}, {y}_{n}) = B_1 {\hat{x}}_{n} + R_{n}^F$ with $\|R_{n}^F\| = {\mathcal O}( \| {\hat{x}}_{n} \|^{1+{\delta_F}'} + \| {\hat{y}}_{n} \|^{1+{\delta_F}'} ) $. \item $G({x}_{n}, {y}_{n}) = B_2{\hat{x}}_{n} + B_3{\hat{y}}_{n} + R_{n}^{G}$ with $\|R_n^{G}\| = {\mathcal O}( \| {\hat{x}}_{n} \|^{1+{\delta_G}'} + \| {\hat{y}}_{n} \|^{1+{\delta_G}'} ) $. \item $H({y}_{n+1}) - H({y}_{n}) = H^\star ({y}_{n+1}-{y}_{n}) + R_{n}^{
abla H} + R_{n}^H $ with $H^\star := 
abla H({y}^\star)$, $\|R_{n}^H\| = {\mathcal O} (\|{y}_{n+1}-{y}_{n}\|^{1+{\delta_H}'} )$ and $R_{n}^{
abla H} = (
abla H({y}_{n}) - 
abla H({y}^{\star}))({y}_{n+1}-{y}_{n})$. \end{enumerate}

The proof is structured into three parts: we derive the one-step recursion first for ${\check{y}}_{n}$, followed by ${\check{x}}_{n}$, and finally ${\check{z}}_{n}$. To begin, we take the update rules for ${\hat{x}}_{n}$ and ${\hat{y}}_{n}$, as outlined below.  egin{align} {\hat{x}}_{n+1} & = {\hat{x}}_n - \alpha_n F(x_n, y_n) - \alpha_n \xi_n + H(y_n) - H(y_{n+1}), \ {\hat{y}}_{n+1} & = {\hat{y}}_n -  eta_n G(H(y_n), y_n) +  eta_n ( G(H(y_n), y_n) - G(x_n, y_n) ) -  eta_n \psi_n. \end{align} 	extbf{Part 1: one-step recursion for ${\check{y}}_{n}$}. By Proposition~ef{prop:operator-decom}, we can rewrite the update rule of ${\hat{y}}_{n}$ in \eqref{eq:yhat} as  egin{align} {\hat{y}}_{n+1} = (I -  eta_{n} B_3) {\hat{y}}_{n} -  eta_{n} B_2 {\hat{x}}_{n} -  eta_n \psi_n -  eta_n R_n^G. \end{align} Then from the definition of ${\check{y}}_{n}$ and \eqref{eq:yhat-decom}, we have  egin{align} {\check{y}}_{n+1} & = \sqrt{  rac{  eta_{n-1} }{  eta_{n} } } ({I} -  eta_{n} B_3) {\check{y}}_{n} - \sqrt{  eta_{n} \alpha_{n-1} } B_2 {\check{x}}_{n} - \sqrt{ eta_{n}} \psi_{n} - \sqrt{ eta_{n}} R_{n}^G 
onumber \ & = \left( {I} -  eta_{n} B_3 +  rac{ 	ilde{ eta}  eta_{n} }{2} {I} ight) {\check{y}}_{n} - \sqrt{ eta_{n} \alpha_{n} } B_2 {\check{x}}_{n} - \sqrt{ eta_n} \psi_{n} + R_{n}^y, \end{align} where  egin{align}  egin{split} R_{n}^y & = \underbrace{ \left( \sqrt{  rac{  eta_{n-1} }{ eta_{n}} } - 1 -  rac{ 	ilde{ eta}  eta_{n} }{2} ight) {\check{y}}_{n} }_{=: R_{n,1}^y} + \underbrace{ (  eta_{n} - \sqrt{  eta_{n}  eta_{n-1} } ) B_3 {\check{y}}_{n} \vphantom{ \left( \sqrt{  rac{  eta_{n-1} }{ eta_{n}} } ight) } }_{ =:R_{n,2}^y } \ & \quad \ + \underbrace{ ( \sqrt{  eta_{n} \alpha_{n} } - \sqrt{  eta_{n} \alpha_{n-1} } ) B_2 {\check{x}}_{n} \vphantom{ \left( \sqrt{  rac{  eta_{n-1} }{ eta_{n}} } ight) } }_{=: R_{n,3}^y } - \underbrace{ \sqrt{ eta_{n}} R_{n}^G \vphantom{ \left( \sqrt{  rac{  eta_{n-1} }{ eta_{n}} } ight) } }_{ =: R_{n,4}^y }. \end{split} \end{align} By Assumption~ef{assump:stepsize-twotime}, we have  egin{align} \sqrt{  rac{  eta_{n-1} }{  eta_{n} } } & = \sqrt{ 1 +  eta_{n-1} (  eta_{n}^{-1} -  eta_{n-1}^{-1} ) } = \sqrt{1 + 	ilde{ eta}  eta_{n-1} + o( eta_{n-1}) } 
onumber \ & = \sqrt{1 + 	ilde{ eta}  eta_{n} + o( eta_{n}) } = 1 +  rac{ 	ilde{ eta}  eta_{n} }{2} + o( eta_{n}), 
onumber \ \sqrt{  rac{ \alpha_{n-1} }{\alpha_{n}} } & = 1 + {\mathcal O}( eta_n), \qquad \sqrt{  rac{ \kappa_{n-1} }{\kappa_{n}} } = 1 + {\mathcal O}( eta_n). \end{align} It follows that $\| R_{n,1}^y \| + \| R_{n,2}^y \| = o( eta_{n}) \| {\check{y}}_{n} \| = o( eta_{n}^{1/2}) \| {\hat{y}}_{n} \| $ and $\| R_{n,3}^y \| = {\mathcal O}( eta_{n}^{3/2} \alpha_{n}^{1/2}) \| {\check{x}}_{n} \| = o( eta_{n}^{3/2}) \| {\hat{x}}_{n} \| $. Meanwhile, by Proposition~ef{prop:operator-decom}, we have $ \| R_{n,4}^y \| = {\mathcal O}( eta_{n}^{1/2}) ( \| {\hat{x}}_{n} \|^{1+{\delta_G}} + \| {\hat{y}}_{n} \|^{1+{\delta_G}} ) $. Note that in Assumption~ef{assump:stepsize-twotime}, we require $\alpha_{n}^{1+{\delta_G}} = o( eta_{n}) $. Then we have  egin{align} \| R_{n}^y \| = o( eta_{n}^{1/2}) \| {\hat{y}}_{n} \| + o( eta_{n}^{3/2}) \| {\hat{x}}_{n} \| + {\mathcal O}( eta_{n}) \,  rac{ \alpha_{n}^{ (1+{\delta_G}) / 2 } }{  eta_{n}^{1/2} } \cdot  rac{ \| {\hat{x}}_{n} \|^{1+{\delta_G}} + \| {\hat{y}}_{n} \|^{1+{\delta_G}} } {\alpha_{n}^{(1+{\delta_G})/2} }. \end{align} By Assumption~ef{assump:mart-decouple-rate}, it follows that $ {\mathbb E} \| {\mathbb E}[ R_{n}^y | {\mathcal F}_{n} ] \| \le {\mathbb E} \| R_{n}^y \| = o( eta_{n})$ and ${\mathbb E} \| R_{n}^y \|^2 = o( eta_{n}^2)$. Moreover, by Proposition~ef{prop:FG-reduce-order}, we have that \eqref{eq:lem:check-twotime:Ry-upper} holds with ${\delta_G}$ replaced by ${\delta_G} / 2$. For $2 \le p \le  rac{4}{1+{\delta_G} / 2}$, it follows that  egin{align*} {\mathbb E} \| R_{n}^y \|^p = o( eta_{n}) + o(  eta_{n} \cdot  eta_{n}^{p-1} / \alpha_{n}^{ p {\delta_G} / 2} ) = o( eta_{n}), \end{align*} where the last step is due to $p-1 \ge p/2 \ge p {\delta_G} / 2$. \vspace{0.2cm} 	extbf{Part 2: one-step recursion for ${\check{x}}_{n}$}. By Proposition~ef{prop:operator-decom}, the update rule of ${\hat{x}}_{n}$ in \eqref{eq:xhat} can be rewritten as  egin{align} {\hat{x}}_{n+1} & = ({I} - \alpha_{n} B_1) {\hat{x}}_{n} + H^\star ({y}_{n} - {y}_{n+1}) - \alpha_{n} \xi_{n} - R_{n}^{
abla H} - R_{n}^{H} - \alpha_{n} R_{n}^F 
