abla H} - R_{n}^H - \alpha_{n} R_{n}^F +  eta_n H^\star R_{n}^G. \end{split} \end{align} Then from the definition of ${\check{x}}_{n}$, we have  egin{align} {\check{x}}_{n+1} & = \sqrt{  rac{\alpha_{n-1}}{\alpha_{n}} } ({I} - \alpha_{n} B_1 +  eta_n H^\star B_2) {\check{x}}_{n} + \sqrt{  rac{ eta_{n-1}}{\alpha_{n}} }  eta_{n} H^\star B_3 {\check{y}}_{n} - \sqrt{ \alpha_{n} } \xi_{n} +  rac{  eta_{n} }{ \sqrt{ \alpha_{n} } } H^\star \psi_{n} 
onumber \ & \qquad -  rac{1}{ \sqrt{\alpha_{n}} } R_{n}^{
abla H} -  rac{1}{\sqrt{\alpha_{n}}} R_{n}^{H} - \sqrt{\alpha_{n}} R_{n}^F +  rac{ eta_{n}}{\sqrt{ \alpha_{n} }} H^\star R_{n}^G 
onumber \ & = ({I} - \alpha_{n} B_1) {\check{x}}_{n} - \sqrt{\alpha_{n}} 	ilde{\xi}_{n} + R_{n}^x, \end{align} where $	ilde{\xi}_{n} := \xi_{n} - \kappa_{n} H^\star \psi_{n} = \xi_{n} -  rac{ eta_{n}}{\alpha_{n}} H^\star \psi_{n}$ and  egin{align}  egin{split} R_{n}^x & = \underbrace{ \left( \sqrt{  rac{\alpha_{n-1}}{\alpha_{n}} } - 1 ight) {\check{x}}_{n} }_{=: R_{n,1}^x} + \underbrace{ (\alpha_{n} - \sqrt{ \alpha_{n} \alpha_{n-1} }) B_1 {\check{x}}_{n} \vphantom{\left( \sqrt{  rac{\alpha_{n-1}}{\alpha_{n}} } ight) } }_{=: R_{n,2}^x} + \underbrace{ \sqrt{ rac{ \alpha_{n-1} }{ \alpha_{n} } }  eta_{n} H^\star B_2 {\check{x}}_{n} \vphantom{\left( \sqrt{  rac{\alpha_{n-1}}{\alpha_{n}} } ight) }}_{=: R_{n,3}^x} \ & \qquad + \underbrace{ \sqrt{  rac{ eta_{n-1}}{\alpha_{n}} }  eta_{n} H^\star B_3 {\check{y}}_{n} \vphantom{\left( \sqrt{  rac{\alpha_{n-1}}{\alpha_{n}} } ight) } }_{=: R_{n,4}^x} - \underbrace{  rac{1}{ \sqrt{\alpha_{n}} } R_{n}^{
abla H} }_{=: R_{n,5}^x} - \underbrace{  rac{1}{\sqrt{\alpha_{n}}} R_{n}^{H} }_{=: R_{n,6}^x} - \underbrace{ \sqrt{\alpha_{n}} R_{n}^F \vphantom{ rac{ eta_{n}}{\sqrt{ \alpha_{n} } } } }_{=:R_{n,7}^x } + \underbrace{  rac{ eta_{n}}{\sqrt{ \alpha_{n} } } H^\star R_{n}^G }_{=:R_{n,8}^x}. \end{split} \end{align} By \eqref{eq:lem:check-twotime:sqrtalpha}, we have $\| R_{n,1}^x \| + \| R_{n,2}^x \| = {\mathcal O}( eta_{n}) \| {\check{x}}_{n} \| = {\mathcal O}( eta_{n} \alpha_{n}^{-1/2} ) \| {\hat{x}}_{n} \| $. By Assumption~ef{assump:stepsize-twotime}, we have $\| R_{n,3}^x \| + \| R_{n,4}^x \| = {\mathcal O}( eta_{n}) \| {\check{x}}_{n} \| + {\mathcal O} (  eta_{n}^{3/2} \alpha_{n}^{-1/2} ) \| {\check{y}}_{n} \| = {\mathcal O}( eta_{n} \alpha_{n}^{-1/2} ) ( \| {\hat{x}}_{n} \| + \| {\hat{y}}_{n} \| ) $. For $R_{n,5}^x$ and $R_{n,6}^x$, from the definition of ${\mathcal F}_{n}$, Assumption~ef{assump:smooth} and Proposition~ef{prop:operator-decom}, we have  egin{align*} \| {\mathbb E} [ R_{n}^{
abla H} | {\mathcal F}_{n} ] \| & = \| (
abla H ({y}_{n}) - 
abla H ({y}^\star)) {\mathbb E}[ {y}_{n+1} - {y}_{n} | {\mathcal F}_{n} ] \| \ & =  eta_{n} \| (
