abla H ({y}^\star)) G({x}_{n}, {y}_{n}) \| \le  eta_{n} {\widetilde{S}_H} \| {\hat{y}}_{n} \|^{\delta_H} \| G({x}_{n}, {y}_{n}) \| \ \| R_{n}^{
abla H} \| & \le {\widetilde{S}_H} \| {\hat{y}}_{n} \|^{{\delta_H}} \| {y}_{n+1} - {y}_{n} \| , \ \| R_{n}^H \| & = {\mathcal O} ( \| {y}_{n+1} - {y}_{n} \|^{1+{\delta_H}} ), \ \| G({x}_{n}, {y}_{n}) \| & = \| G({x}_{n}, {y}_{n}) - G( H({y}_{n}), {y}_{n} ) + G( H({y}_{n}), {y}_{n} ) - G( H({y}^\star), {y}^\star ) \| \ & \le {L}_{G,x} \| {\hat{x}}_{n} \| + {L}_{G,y} \| {\hat{y}}_{n} \|, \ \| {y}_{n+1} - {y}_{n} \| & \le  eta_{n} \| G({x}_{n}, {y}_{n}) \| +  eta_{n} \| \psi_{n} \|. \end{align*} Then by Young's inequality and Jensen's inequality, we have  egin{align*} \| {\mathbb E}[ R_{n,5}^x | {\mathcal F}_n ] \| & = {\mathcal O} ( eta_{n} \alpha_{n}^{-1/2}) ( \| {\hat{x}}_{n} \|^{1+{\delta_H}} + \| {\hat{y}}_{n} \|^{1+{\delta_H}} ), \ \| R_{n,5}^x \| & = {\mathcal O} ( eta_{n} \alpha_{n}^{-1/2}) ( \| {\hat{x}}_{n} \|^{1+{\delta_H}} + \| {\hat{y}}_{n} \|^{1+{\delta_H}} + \| {\hat{y}}_{n} \|^{\delta_H} \| \psi_{n} \| ), \ \| R_{n,6}^x \| & = {\mathcal O} ( eta_{n}^{1+{\delta_H}} \alpha_{n}^{-1/2}) ( \| {\hat{x}}_{n} \|^{1+{\delta_H}} + \| {\hat{y}}_{n} \|^{1+{\delta_H}} + \| \psi_{n} \|^{1+{\delta_H}} ). \end{align*} Moreover, Proposition~ef{prop:operator-decom} also implies $\| R_{n,7}^x \| = {\mathcal O}(\alpha_{n}^{1/2}) ( \| {\hat{x}}_{n} \|^{1+{\delta_F}} + \| {\hat{y}}_{n} \|^{1+{\delta_F}} )$ and $ \| R_{n,8}^x \| = {\mathcal O} ( eta_{n} \alpha_{n}^{-1/2}) ( \| {\hat{x}}_{n} \|^{1+{\delta_G}} + \| {\hat{y}}_{n} \|^{1+{\delta_G}} ) $. Summarizing the above results, we obtain  egin{align}  egin{split} \| {\mathbb E} [ R_{n}^x | {\mathcal F}_n ] \| & = {\mathcal O}(  eta_{n} \alpha_{n}^{-1/2}) (\| {\hat{x}}_{n} \| + \| {\hat{y}}_{n} \| ) + {\mathcal O} ( eta_{n} \alpha_{n}^{-1/2}) ( \| {\hat{x}}_{n} \|^{1+{\delta_H}} + \| {\hat{y}}_{n} \|^{1+{\delta_H}} ) \ & \quad \ + {\mathcal O} ( eta_{n}^{1+{\delta_H}} \alpha_{n}^{-1/2}) \| \psi_{n} \|^{1+{\delta_H}} + {\mathcal O}(\alpha_{n}^{1/2}) ( \| {\hat{x}}_{n} \|^{1+{\delta_F}} + \| {\hat{y}}_{n} \|^{1+{\delta_F}} ) \ & \quad \ + {\mathcal O} ( eta_{n} \alpha_{n}^{-1/2}) ( \| {\hat{x}}_{n} \|^{1+{\delta_G}} + \| {\hat{y}}_{n} \|^{1+{\delta_G}} ), \ \| R_{n}^x \| & = {\mathcal O}( \| {\mathbb E} [ R_{n}^x | {\mathcal F}_n ] \| ) + {\mathcal O} ( eta_{n} \alpha_{n}^{-1/2}) \| {\hat{y}}_{n} \|^{\delta_H} \| \psi_{n} \|. \end{split} \end{align} Note that Assumption~ef{assump:stepsize-twotime} requires $\alpha_{n}^{1+{\delta_F}} = o ( eta_{n})$, $ eta_{n}^{(1+{\delta_H}) / 2 } = {\mathcal O}(\alpha_{n})$. By Assumption~ef{assump:mart-decouple-rate}, we have $ {\mathbb E} \| {\mathbb E} [ R_{n}^x | {\mathcal F}_n ] \| = {\mathcal O}(  eta_{n} +  eta_{n}^{1+{\delta_H}} \alpha_{n}^{-1/2} + \alpha_{n}^{1 + {\delta_F}/2}) = o(\sqrt{ eta_{n} \alpha_{n}}) $. Meanwhile, since ${\hat{y}}_{n} \in {\mathcal F}_{n}$, Assumption~ef{assump:noise-fclt} implies ${\mathbb E} \| {\hat{y}}_{n} \|^{2{\delta_H}} \| \psi_{n} \|^2 = {\mathcal O}( {\mathbb E} \| {\hat{y}}_{n} \|^{2{\delta_H}})$. By Assumption~ef{assump:mart-decouple-rate}, we have $ {\mathbb E} \| R_{n}^x \|^2 = {\mathcal O}(  eta_{n}^2 +  eta_{n}^{2+{\delta_H}} \alpha_{n}^{-1} + \alpha_{n}^{2 + {\delta_F}}) = {\mathcal O}( eta_n \alpha_n) $. Moreover, by Propositions~ef{prop:H-reduce-order} and ef{prop:FG-reduce-order}, we have that \eqref{eq:lem:check-twotime:Rx-upper} holds after replacing ${\delta_H}, {\delta_F}, {\delta_G}$ with ${\delta_H}/2, {\delta_F}/2, {\delta_G}/2$ respectively. For $2 \le p \le  rac{4}{1 + ({\delta_H} \vee {\delta_F} \vee {\delta_G}) / 2 }$, one can check ${\mathbb E} \| R_{n}^x \|^p = o(\alpha_{n}) $. \vspace{0.2cm} 	extbf{Part 3: one-step recursion for ${\check{z}}_{n}$}. From the definition of ${\check{z}}_{n}$ and the update rules of ${\check{y}}_{n}$ and ${\check{x}}_{n}$ in \eqref{eq:lem:check-twotime:y-update} and \eqref{eq:lem:check-twotime:x-update} , we have  egin{align*} {\check{z}}_{n+1} & = {\check{y}}_{n+1} - \sqrt{\kappa_{n}} B_2 B_1^{-1} {\check{x}}_{n+1} \ & = \left( {I} -  eta_{n} B_3 + 